class _FakeProc:
    """Stands in for subprocess.Popen of the claude CLI."""

    def __init__(self, stdout, returncode=0, stderr=""):
        self._stdout = stdout
        self.returncode = returncode
        self._stderr = stderr
        self.pid = 12345

    def communicate(self, input=None, timeout=None):
        if isinstance(self._stdout, Exception):
            raise self._stdout
        return self._stdout, self._stderr

    def wait(self):
        return self.returncode


def _patch_run(monkeypatch, response, capture=None):
    def fake_popen(argv, **kwargs):
        if capture is not None:
            capture["argv"] = argv
            capture["kwargs"] = kwargs
        if isinstance(response, subprocess.TimeoutExpired):
            return _FakeProc(response)
        if isinstance(response, Exception):
            raise response
        return response

    monkeypatch.setattr(subprocess, "Popen", fake_popen)
    monkeypatch.setattr("os.killpg", lambda pid, sig: None)


class TestArgvConstruction:
    def test_full_argv(self, monkeypatch):
        capture = {}
        _patch_run(monkeypatch, _FakeProc(json.dumps(_cli_result())), capture)
        backend.run_agent(
            "the prompt",
            schema={"type": "object"},
            model="sonnet",
            allowed_tools=["Read", "Grep"],
            tools="Read,Grep",
            cwd="/tmp",
            effort="low",
            timeout_s=42,
        )
        argv = capture["argv"]
        assert argv[:2] == ["claude", "-p"]
        assert "the prompt" not in argv  # prompt rides stdin
        assert argv[argv.index("--tools") + 1] == "Read,Grep"
        assert argv[argv.index("--permission-mode") + 1] == "dontAsk"
        assert "--output-format" in argv and argv[argv.index("--output-format") + 1] == "json"
        assert "--no-session-persistence" in argv
        assert "--bare" not in argv
        assert argv[argv.index("--model") + 1] == "sonnet"
        assert argv[argv.index("--effort") + 1] == "low"
        assert argv[argv.index("--allowedTools") + 1] == "Read,Grep"
        assert json.loads(argv[argv.index("--json-schema") + 1]) == {"type": "object"}
        assert capture["kwargs"]["cwd"] == "/tmp"

