class TestLoadResolvedSchema:
    def test_strips_generated_marker(self):
        schema = backend.load_resolved_schema("agent-output")
        assert "_generated" not in schema
        assert schema["type"] == "object"
        assert "findings" in schema["properties"]

    def test_no_root_composition(self):
        # --json-schema rejects root-level composition like StructuredOutput.
        for name in ("agent-output", "validation-output"):
            schema = backend.load_resolved_schema(name)
            for keyword in ("allOf", "anyOf", "oneOf"):
                assert keyword not in schema, f"{name} has root {keyword}"


class TestAgentTrace:
    def test_trace_line_written_on_success(self, monkeypatch, tmp_path):
        import json as _json

        _patch_run(monkeypatch, _FakeProc(_json.dumps(_cli_result())))
        trace = tmp_path / "agent-trace.jsonl"
        backend.run_agent(
            "the prompt",
            schema={"type": "object"},
            model="sonnet",
            allowed_tools=["Read"],
            cwd="/tmp",
            trace_file=trace,
            label="impl/full-scope",
        )
        lines = trace.read_text().strip().splitlines()
        assert len(lines) == 1
        record = _json.loads(lines[0])
        assert record["label"] == "impl/full-scope"
        assert record["prompt"] == "the prompt"
        assert record["error"] is None
        assert record["cost_usd"] == 0.0123
        assert record["result"]["structured_output"] == {"ok": True}
        assert record["elapsed_s"] >= 0

    def test_trace_line_written_on_failure_and_appends(self, monkeypatch, tmp_path):
        import json as _json

        trace = tmp_path / "agent-trace.jsonl"
        _patch_run(monkeypatch, _FakeProc("garbage", returncode=1, stderr="bad"))
        backend.run_agent(
            "p", schema=None, model="haiku", allowed_tools=[], cwd="/tmp",
            trace_file=trace, label="a",
        )
        _patch_run(monkeypatch, subprocess.TimeoutExpired(cmd=["claude"], timeout=5))
        backend.run_agent(
            "p", schema=None, model="haiku", allowed_tools=[], cwd="/tmp",
            trace_file=trace, label="b", timeout_s=5,
        )
        records = [_json.loads(x) for x in trace.read_text().strip().splitlines()]
        assert len(records) == 2
        assert "malformed CLI result" in records[0]["error"]
        assert records[0]["result"]["stderr"] == "bad"
        assert "timeout" in records[1]["error"]

